'use client';

import { TrendingUp, TrendingDown, DollarSign } from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, ResponsiveContainer, Tooltip } from 'recharts';

interface StockData {
  symbol: string;
  name: string;
  currentPrice: number;
  change: number;
  changePercent: number;
  currency: string;
  lastUpdated: string;
  historicalData: Array<{
    date: string;
    price: number;
  }>;
}

interface StockCardProps {
  data: StockData;
}

export default function StockCard({ data }: StockCardProps) {
  const isPositive = data.change >= 0;
  
  // Format the historical data for the chart
  const chartData = data.historicalData.map(item => ({
    date: new Date(item.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
    price: item.price
  }));

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: data.currency,
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(value);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg border border-gray-200 dark:border-gray-700 max-w-md mx-auto my-4">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div>
          <h3 className="text-lg font-bold text-gray-900 dark:text-white">{data.symbol}</h3>
          <p className="text-sm text-gray-600 dark:text-gray-400">{data.name}</p>
        </div>
        <div className="p-2 bg-green-100 dark:bg-green-900 rounded-lg">
          <DollarSign className="w-6 h-6 text-green-600 dark:text-green-400" />
        </div>
      </div>

      {/* Current Price */}
      <div className="mb-4">
        <div className="text-3xl font-bold text-gray-900 dark:text-white mb-1">
          {formatCurrency(data.currentPrice)}
        </div>
        <div className={`flex items-center space-x-1 ${isPositive ? 'text-green-600' : 'text-red-600'}`}>
          {isPositive ? (
            <TrendingUp className="w-4 h-4" />
          ) : (
            <TrendingDown className="w-4 h-4" />
          )}
          <span className="font-semibold">
            {isPositive ? '+' : ''}{formatCurrency(data.change)}
          </span>
          <span className="text-sm">
            ({isPositive ? '+' : ''}{data.changePercent.toFixed(2)}%)
          </span>
        </div>
        <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
          Last updated: {formatDate(data.lastUpdated)}
        </p>
      </div>

      {/* Chart */}
      <div className="mb-4">
        <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
          10-Day Price History
        </h4>
        <div className="h-32">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData}>
              <XAxis 
                dataKey="date" 
                axisLine={false}
                tickLine={false}
                tick={{ fontSize: 10, fill: '#6B7280' }}
              />
              <YAxis 
                hide
                domain={['dataMin - 5', 'dataMax + 5']}
              />
              <Tooltip
                contentStyle={{
                  backgroundColor: '#374151',
                  border: 'none',
                  borderRadius: '8px',
                  color: 'white',
                  fontSize: '12px'
                }}
                formatter={(value: number) => [formatCurrency(value), 'Price']}
              />
              <Line
                type="monotone"
                dataKey="price"
                stroke={isPositive ? '#10B981' : '#EF4444'}
                strokeWidth={2}
                dot={false}
                activeDot={{ r: 4, fill: isPositive ? '#10B981' : '#EF4444' }}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Price Range */}
      <div className="grid grid-cols-2 gap-4 text-sm">
        <div>
          <p className="text-gray-500 dark:text-gray-400">10-Day Low</p>
          <p className="font-semibold text-gray-900 dark:text-white">
            {formatCurrency(Math.min(...data.historicalData.map(d => d.price)))}
          </p>
        </div>
        <div>
          <p className="text-gray-500 dark:text-gray-400">10-Day High</p>
          <p className="font-semibold text-gray-900 dark:text-white">
            {formatCurrency(Math.max(...data.historicalData.map(d => d.price)))}
          </p>
        </div>
      </div>
    </div>
  );
} 