'use client';

import { useState, useEffect, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import ChatMessage from './ChatMessage';
import ChatInput from './ChatInput';
import Sidebar from './Sidebar';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  components?: Array<{
    type: string;
    data: any;
  }>;
}

interface Chat {
  id: string;
  title: string;
  lastMessage: string;
  timestamp: Date;
  messages: Message[];
}

export default function ChatInterface() {
  const [chats, setChats] = useState<Chat[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const currentChat = chats.find(chat => chat.id === currentChatId);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [currentChat?.messages]);

  const createNewChat = () => {
    const newChatId = uuidv4();
    const newChat: Chat = {
      id: newChatId,
      title: 'New Chat',
      lastMessage: '',
      timestamp: new Date(),
      messages: []
    };
    setChats(prev => [newChat, ...prev]);
    setCurrentChatId(newChatId);
  };

  const deleteChat = (chatId: string) => {
    setChats(prev => prev.filter(chat => chat.id !== chatId));
    if (currentChatId === chatId) {
      const remainingChats = chats.filter(chat => chat.id !== chatId);
      setCurrentChatId(remainingChats.length > 0 ? remainingChats[0].id : null);
    }
  };

  const updateChatTitle = (chatId: string, firstMessage: string) => {
    const title = firstMessage.length > 30 
      ? firstMessage.substring(0, 30) + '...' 
      : firstMessage;
    
    setChats(prev => prev.map(chat => 
      chat.id === chatId 
        ? { ...chat, title }
        : chat
    ));
  };

  const sendMessage = async (content: string) => {
    if (!currentChatId) {
      createNewChat();
      return;
    }

    const userMessage: Message = {
      id: uuidv4(),
      role: 'user',
      content
    };

    // Add user message
    setChats(prev => prev.map(chat => 
      chat.id === currentChatId 
        ? { 
            ...chat, 
            messages: [...chat.messages, userMessage],
            lastMessage: content,
            timestamp: new Date()
          }
        : chat
    ));

    // Update title if this is the first message
    if (currentChat?.messages.length === 0) {
      updateChatTitle(currentChatId, content);
    }

    setIsLoading(true);

    try {
      // Create assistant message
      const assistantMessageId = uuidv4();
      let assistantContent = '';
      let components: Array<{ type: string; data: any }> = [];

      // Add empty assistant message
      setChats(prev => prev.map(chat => 
        chat.id === currentChatId 
          ? { 
              ...chat, 
              messages: [...chat.messages, {
                id: assistantMessageId,
                role: 'assistant',
                content: '',
                components: []
              }]
            }
          : chat
      ));

      // Prepare messages for API
      const messages = [...(currentChat?.messages || []), userMessage].map(msg => ({
        role: msg.role,
        content: msg.content
      }));

      // Stream response
      const response = await fetch('http://localhost:8000/chat/stream', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          messages,
          include_components: true
        }),
      });

      if (!response.body) {
        throw new Error('No response body');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            try {
              const data = JSON.parse(line.slice(6));
              
              if (data.type === 'content') {
                assistantContent += data.content;
                // Update message content
                setChats(prev => prev.map(chat => 
                  chat.id === currentChatId 
                    ? { 
                        ...chat, 
                        messages: chat.messages.map(msg => 
                          msg.id === assistantMessageId 
                            ? { ...msg, content: assistantContent }
                            : msg
                        )
                      }
                    : chat
                ));
              } else if (data.type === 'component') {
                components.push(data.data);
              } else if (data.type === 'replace_content') {
                assistantContent = data.content;
                // Update with final content and components
                setChats(prev => prev.map(chat => 
                  chat.id === currentChatId 
                    ? { 
                        ...chat, 
                        messages: chat.messages.map(msg => 
                          msg.id === assistantMessageId 
                            ? { ...msg, content: assistantContent, components }
                            : msg
                        ),
                        lastMessage: assistantContent.substring(0, 100)
                      }
                    : chat
                ));
              } else if (data.type === 'done') {
                // Final update
                setChats(prev => prev.map(chat => 
                  chat.id === currentChatId 
                    ? { 
                        ...chat, 
                        messages: chat.messages.map(msg => 
                          msg.id === assistantMessageId 
                            ? { ...msg, content: assistantContent, components }
                            : msg
                        ),
                        lastMessage: assistantContent.substring(0, 100)
                      }
                    : chat
                ));
                break;
              } else if (data.type === 'error') {
                console.error('Stream error:', data.error);
                break;
              }
            } catch (e) {
              console.error('Error parsing SSE data:', e);
            }
          }
        }
      }
    } catch (error) {
      console.error('Error sending message:', error);
      // Remove the empty assistant message on error
      setChats(prev => prev.map(chat => 
        chat.id === currentChatId 
          ? { 
              ...chat, 
              messages: chat.messages.filter(msg => msg.id !== assistantMessageId)
            }
          : chat
      ));
    } finally {
      setIsLoading(false);
    }
  };

  // Create initial chat if none exists
  useEffect(() => {
    if (chats.length === 0) {
      createNewChat();
    }
  }, []);

  return (
    <div className="flex h-screen bg-white dark:bg-gray-800">
      <Sidebar
        chats={chats}
        currentChatId={currentChatId}
        onSelectChat={setCurrentChatId}
        onNewChat={createNewChat}
        onDeleteChat={deleteChat}
      />
      
      <div className="flex-1 flex flex-col">
        {currentChat ? (
          <>
            {/* Messages */}
            <div className="flex-1 overflow-y-auto">
              {currentChat.messages.map((message) => (
                <ChatMessage key={message.id} message={message} />
              ))}
              <div ref={messagesEndRef} />
            </div>
            
            {/* Input */}
            <ChatInput onSendMessage={sendMessage} isLoading={isLoading} />
          </>
        ) : (
          <div className="flex-1 flex items-center justify-center">
            <div className="text-center">
              <h2 className="text-2xl font-semibold text-gray-900 dark:text-white mb-4">
                Welcome to ChatGPT Clone
              </h2>
              <p className="text-gray-600 dark:text-gray-400 mb-6">
                Start a new conversation to begin chatting
              </p>
              <button
                onClick={createNewChat}
                className="px-6 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-lg transition-colors"
              >
                Start New Chat
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
} 